PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS organisations(id TEXT PRIMARY KEY, created INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS identities(id TEXT PRIMARY KEY,org TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('resident','manager')),key_hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS properties(id TEXT PRIMARY KEY,org TEXT NOT NULL REFERENCES organisations(id) ON DELETE CASCADE,label TEXT NOT NULL,resident TEXT REFERENCES identities(id));
CREATE INDEX IF NOT EXISTS property_org ON properties(org);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,identity TEXT NOT NULL REFERENCES identities(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,property TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,author TEXT NOT NULL REFERENCES identities(id),title TEXT NOT NULL,description TEXT NOT NULL,room TEXT NOT NULL,measurements TEXT,analysis TEXT,urgent INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'reported',created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reports_property ON reports(property,created);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,report TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,actor TEXT NOT NULL REFERENCES identities(id),kind TEXT NOT NULL,note TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS events_report ON events(report,created);
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY,report TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,bytes BLOB NOT NULL,digest TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS photos_report ON photos(report);
CREATE TABLE IF NOT EXISTS limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires INTEGER NOT NULL);
